   "id": "teloa.mcp-atlassian",
   "kind": "connector",
   "delivery": "managed",
   "version": "1.0.0",
   "upstream": null,
   "taxonomy": {
    "functions": [
     "communication",
     "office-docs"
    ],
    "industries": [
     "general"
    ]
   },
   "connector": {
    "serverName": "atlassian",
    "title": {
     "zh-CN": "Atlassian（Jira & Confluence）",
     "en": "Atlassian (Jira & Confluence)"
    },
    "summary": {
     "zh-CN": "Atlassian 官方 MCP（Rovo MCP 服务），以服务账号 API Key 连接 Jira 和 Confluence，可按 JQL 查询与读取 Issue、创建 Issue、搜索与读取 Confluence 内容。需要组织管理员开启 API Token 认证并创建服务账号 API Key。数据经由 atlassian.com 传输。",
     "en": "Atlassian official MCP (Rovo MCP server) connecting Jira and Confluence with a service-account API key: query and read issues with JQL, create issues, and search and read Confluence content. An org admin must enable API token authentication and create the service-account API key. Data transits atlassian.com."
    },
    "auth": {
     "kind": "secret",
     "vars": [
      {
       "target": "bearer",
       "label": {
        "zh-CN": "Atlassian 服务账号 API Key（由组织管理员创建；个人 API Token 需 Basic 认证，暂不支持）",
        "en": "Atlassian service-account API key (created by an org admin; personal API tokens need Basic auth and are not supported yet)"
       },
       "required": true
      }
     ]
    },
    "recipe": {
     "transport": "streamable-http",
     "url": "https://mcp.atlassian.com/v1/mcp"
    },
    "tools": [
     {
      "name": "getJiraIssue",
      "description": {
       "zh-CN": "获取 Jira Issue 详情",
       "en": "Get a Jira issue"
      },
      "readOnly": true
     },
     {
      "name": "searchJiraIssuesUsingJql",
      "description": {
       "zh-CN": "按 JQL 搜索 Jira Issue",
       "en": "Search Jira issues with JQL"
      },
      "readOnly": true
     },
     {
      "name": "createJiraIssue",
      "description": {
       "zh-CN": "创建 Jira Issue",
       "en": "Create a Jira issue"
      },
      "readOnly": false
     },
     {
      "name": "searchConfluence",
      "description": {
       "zh-CN": "搜索 Confluence 内容",
       "en": "Search Confluence content"
      },
      "readOnly": true
     },
     {
      "name": "getConfluenceContent",
      "description": {
       "zh-CN": "读取 Confluence 页面内容",
       "en": "Read Confluence page content"
      },
      "readOnly": true
     }
    ],
    "upstreamUrl": "https://developer.atlassian.com/cloud/jira/platform/mcp/"
   },
